export default '/**\n * Stackra file contract:\n * Purpose: the "basics" demo of the native ComboBox: a label with a placeholder, and a label with a description.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0310 (decision 6).\n */\nimport type { SelectItem } from "@stackra/ui/contracts";\nimport { ComboBox, useCatalogueText } from "@stackra/ui/native";\nimport { View } from "react-native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { COMBO_BOX_DEMO_KEYS } from "#src/demos/free/combo-box/combo-box-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = COMBO_BOX_DEMO_KEYS.demo_free.combo_box.basics;\nconst C = COMBO_BOX_DEMO_KEYS.demo_free.combo_box.countries;\n\n/** The countries\' ids, in the catalogue\'s order; Andorra is refused. */\nconst COUNTRIES = [\n  "ar",\n  "ad",\n  "au",\n  "at",\n  "be",\n  "br",\n  "ca",\n  "cl",\n  "cz",\n  "dk",\n  "eg",\n  "fi",\n  "fr",\n  "de",\n  "gr",\n  "in",\n  "it",\n  "jp",\n  "ke",\n  "mx",\n  "nl",\n  "no",\n  "es",\n  "se",\n] as const;\n\n/** Type to filter the countries. */\nexport default function Basics() {\n  const t = useCatalogueText(MESSAGES.en);\n  const countries: readonly SelectItem[] = COUNTRIES.map((id) => ({\n    id,\n    label: t(C[id]),\n    isDisabled: id === "ad",\n  }));\n  return (\n    <View className="gap-4">\n      <ComboBox label={t(K.country)} placeholder={t(K.placeholder)} items={countries} />\n      <ComboBox\n        label={t(K.described)}\n        description={t(K.hint)}\n        placeholder={t(K.placeholder)}\n        items={countries}\n      />\n    </View>\n  );\n}\n';
